}

func searchVerifyNodeRunnerFromScript(script string) (string, bool) {
	for _, candidate := range searchVerifyNodeRunners {
		if searchVerifyScriptInvokesRunner(script, candidate.name) {
			return candidate.command, true
		}
	}

func graphVerbFromCommand(command string) (string, bool) {
	for _, segment := range splitShellSegments(command) {
		fields := strings.Fields(segment)
		for index := 0; index < len(fields); index++ {
			word := shellWord(fields[index])
			if word == "" || strings.Contains(word, "=") {
				continue
			}
			base := filepath.Base(word)
			if commandPrefixes[base] {
				continue
			}
			rest := fields[index+1:]
			if base == "entire" && len(rest) > 0 && shellWord(rest[0]) == "graph" {
				if verb, ok := firstGraphVerb(rest[1:]); ok {
					return verb, true
				}
			}
			if base == "entire" && len(rest) > 0 && shellWord(rest[0]) == "sem" {
				if verb, ok := firstSemVerb(rest[1:]); ok {
					return verb, true
				}
			}
			if base == "entire-graph" {
				if verb, ok := firstGraphVerb(rest); ok {
					return verb, true
				}
			}
			break // this segment's command word is something else
		}
	}
	return "", false
}

// firstSemVerb matches the `entire sem <verb>` form. The CLI's own agent instructions recommend
// `entire sem edges` and `entire sem symbols` by name as the deterministic callers/definitions
// lookup, and they were counted in NEITHER arm: not a graph call, and not exploration either — so
// a session driven entirely by them read as a session that used no tool at all. They are counted
// as graph calls; the savings model still prices only graphLocateVerbs, so nothing here is
// credited with a displacement it did not make.
func firstSemVerb(fields []string) (string, bool) {
	if len(fields) == 0 {
		return "", false
	}
	verb := strings.TrimLeft(shellWord(fields[0]), "-")
	if semGraphVerbs[verb] {
		return verb, true
	}
	return "", false
}

func firstGraphVerb(fields []string) (string, bool) {
	if len(fields) == 0 {
		return "", false
	}
	verb := strings.TrimLeft(shellWord(fields[0]), "-")
	switch verb {
	case "v":
		verb = "version"
	case "h":
		verb = "help"
	}
	if graphVerbs[verb] {
		return verb, true
	}
	return "", false
}

func shellWord(field string) string {
	return strings.Trim(field, "\"'`()")
}

// explorationKindFromToolUse classifies the tool calls the graph is meant to displace.
func explorationKindFromToolUse(block contentBlock) (string, bool) {
	switch block.Name {
	case "Read":
		if _, ok := block.Input["offset"]; ok {
			return kindReadRange, true
		lines = lines[:len(lines)-1]
	}
	snippetStart := result.SnippetStartLine
	if snippetStart <= 0 {
		snippetStart = result.StartLine
	}
	if snippetStart <= 0 {
		snippetStart = 1
	}
	focusLine := result.FocusLine
	if focusLine <= 0 {
		focusLine = snippetStart
	}
	focus := focusLine - snippetStart
	if focus < 0 || focus >= len(lines) {
		focus = len(lines) / 2
		focusLine = snippetStart + focus
	}
	if len(lines) == 0 {
		return fitAgentSearchLocation(result.Rank, result.FilePath, focusLine, name, tag, scored, budget)
	}

	// Prefer the widest balanced span containing the focus line. The location
	// in the header is rebuilt for each candidate, so it always describes the
	// lines actually displayed rather than the original untrimmed region.
	//
	// The header tier is the OUTER loop: a block gives up body lines before it
	// gives up its rank, name and score. With span outermost, the widest span
	// that fit under ANY header won, so a tight budget bought one or two more
	// body lines by printing the head result as a bare `path:line *` — the
	// minimal header, which carries no rank, no name and no score. That is the
	// one signal agentSearchLocationHeaders calls not optional, dropped from
	// the result an agent is most likely to act on, to show lines it would
	// read anyway. So the ladder is: rich header with body, compact header
