L499:         directory: "/"
L500:         patterns: ["nginx", "redis"]
L501:         multi-ecosystem-group: "infrastructure"
L502: 
L503:       - package-ecosystem: "terraform"
L504:         directory: "/"
L505:         patterns: ["aws"]
L506:         multi-ecosystem-group: "infrastructure"
L507:     `# Basic `dependabot.yml` file defining a multi-ecosystem-group
L508:     version: 2
L509: 
