// coldBuildLockChildEnv selects the role a re-executed test binary plays.
const coldBuildLockChildEnv = "ENTIRE_GRAPH_TEST_COLD_BUILD_LOCK_CHILD"

const (
	coldBuildLockRoleQuery    = "query"
	coldBuildLockRoleComplete = "complete"
	coldBuildLockRoleHold     = "hold"
)

var coldBuildLockQueryOptions = SearchOptions{Profile: ProfileFull, TopK: 10, defaultIndexedFilesForTest: 2}

// TestColdBuildLockChild is not a test on its own: it is the body a
// re-executed test binary runs as one of several concurrent processes.
func fileChangesWithRelations(ctx context.Context, repo, revision, repoKey string, files []FileRecord) []RelationRecord {
	if revision == "" {
		return nil
	}
	cochanges, err := gitutil.FileCochanges(ctx, repo, revision, 256)
	if err != nil || len(cochanges) == 0 {
		return nil
	}
	known := map[string]bool{}
	for _, file := range files {
		known[file.Path] = true
	}
	var relations []RelationRecord
	for _, pair := range cochanges {
		if !known[pair.Left] || !known[pair.Right] {
			continue
		}
		confidence := 0.55
		if pair.Count >= 3 {
			confidence = 0.7
		}
		relations = append(relations, RelationRecord{
			RecordType:    "relation",
			FromID:        fileID(repoKey, pair.Left),
			ToID:          fileID(repoKey, pair.Right),
